//! Elide dense machine-generated lines (minified JS/CSS, base64, RSC payloads).
//!
//! Tool outputs that dump a fetched web page, a bundled asset, or an encoded
//! blob arrive as a few very long lines with almost no whitespace. None of the
//! structural compressors can do anything with them: they are not code an AST
//! walker can prune, not a log, not a table, and the HTML extractor returns
//! the whole thing (or nothing) once the page is mostly `<script>`. The result
//! is a multi-thousand-token block that rides through the router at ratio 1.0.
//!
//! This keeps a head and a tail of each such line and replaces the middle
//! with a one-line marker. Deliberately dumb: a line is "dense" when it is
//! long AND has a tiny fraction of spaces. Prose, code, logs, JSON with any
//! indentation, CSV, and markdown all carry far more than 6% spaces, so they
//! are never touched. A JSON-shaped line is left to SmartCrusher, and a lone
//! dense value (JWT, signed URL, PATH) is below the per-block minimum.

/// A line is dense only at or above this many chars.
pub const MIN_LINE_CHARS: usize = 300;
/// …and only when spaces are below this fraction of its length.
pub const MAX_SPACE_RATIO: f64 = 0.06;
/// A single dense line (a JWT, a signed URL) is a value the agent asked for,
/// not a dump: a block is only elided when its dense lines add up to at least
/// this many chars. Real bundle dumps are tens of KB.
pub const MIN_DENSE_TOTAL_CHARS: usize = 2000;
/// Kept head chars per elided line.
pub const HEAD_CHARS: usize = 160;
/// Kept tail chars per elided line.
pub const TAIL_CHARS: usize = 80;

/// True when `line` is long, nearly whitespace-free, and not JSON-shaped.
///
/// A compact JSON value (or a run of them) on one line is also nearly
/// whitespace-free, but that is SmartCrusher's job; the elider must never
/// pre-empt it.
pub fn is_dense_line(line: &str) -> bool {
    let n = line.chars().count();
    // Tabs: TSV / `psql -A` rows pass the space ratio but are data the agent
    // asked for; minified assets and encoded blobs never carry tabs.
    if n < MIN_LINE_CHARS || line.contains('\t') {
        return false;
    }
    let spaces = line.chars().filter(|&c| c == ' ').count();
    if spaces as f64 / n as f64 >= MAX_SPACE_RATIO {
        return false;
    }
    let stripped = line.trim();
    let (first, last) = (stripped.chars().next(), stripped.chars().last());
    !matches!(
        (first, last),
        (Some('{'), Some('}')) | (Some('['), Some(']'))
    )
}

/// Return `(text_with_dense_lines_elided, lines_elided)`.
///
/// Byte-identical to the input (and `0`) when no line is dense, so callers
/// can use inequality as the "did anything" signal. Line endings are
/// preserved: the split is on `'\n'` only, so `'\r'` stays on its line.
pub fn elide_dense_lines(text: &str) -> (String, usize) {
    if text.chars().count() < MIN_LINE_CHARS {
        return (text.to_string(), 0);
    }
    let lines: Vec<&str> = text.split('\n').collect();
    if lines
        .iter()
        .filter(|l| is_dense_line(l))
        .map(|l| l.chars().count())
        .sum::<usize>()
        < MIN_DENSE_TOTAL_CHARS
    {
        return (text.to_string(), 0);
    }
    let mut out = Vec::with_capacity(lines.len());
    let mut n_elided = 0;
    for line in lines {
        if is_dense_line(line) {
            let chars: Vec<char> = line.chars().collect();
            let omitted = chars.len() - HEAD_CHARS - TAIL_CHARS;
            let head: String = chars[..HEAD_CHARS].iter().collect();
            let tail: String = chars[chars.len() - TAIL_CHARS..].iter().collect();
            out.push(format!(
                "{head} ...[{omitted} chars of dense machine-generated content elided]... {tail}"
            ));
            n_elided += 1;
        } else {
            out.push(line.to_string());
        }
    }
    if n_elided == 0 {
        return (text.to_string(), 0);
    }
    (out.join("\n"), n_elided)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dense_line(len: usize) -> String {
        "x".repeat(len)
    }

    #[test]
    fn short_text_passes_through() {
        let (out, n) = elide_dense_lines("hello");
        assert_eq!(out, "hello");
        assert_eq!(n, 0);
    }

    #[test]
    fn prose_and_code_are_untouched() {
        let prose = "the quick brown fox jumps over the lazy dog ".repeat(20);
        let (out, n) = elide_dense_lines(&prose);
        assert_eq!(out, prose);
        assert_eq!(n, 0);
    }

    #[test]
    fn json_shaped_lines_belong_to_smart_crusher() {
        let line = format!("{}{}{}", "{", "a".repeat(400), "}");
        assert!(!is_dense_line(&line));
        let arr = format!("[{}]", "1,".repeat(200));
        assert!(!is_dense_line(&arr));
    }

    #[test]
    fn tabbed_rows_are_data_not_dumps() {
        let line = format!("{}\t{}", "a".repeat(200), "b".repeat(200));
        assert!(!is_dense_line(&line));
    }

    #[test]
    fn lone_dense_value_is_below_minimum() {
        // One 500-char dense line: dense by itself, but the block total
        // (500) is under MIN_DENSE_TOTAL_CHARS.
        let (out, n) = elide_dense_lines(&dense_line(500));
        assert_eq!(n, 0);
        assert_eq!(out, dense_line(500));
    }

    #[test]
    fn bundle_dump_elides_middle_keeps_head_tail() {
        let line_a = "a".repeat(3000);
        let line_b = "b".repeat(3000);
        let text = format!("header line\n{line_a}\nfooter line\n{line_b}");
        let (out, n) = elide_dense_lines(&text);
        assert_eq!(n, 2);
        let lines: Vec<&str> = out.split('\n').collect();
        assert_eq!(lines.len(), 4);
        assert_eq!(lines[0], "header line");
        assert_eq!(lines[2], "footer line");
        assert!(lines[1].starts_with(&"a".repeat(HEAD_CHARS)));
        assert!(lines[1].ends_with(&"a".repeat(TAIL_CHARS)));
        assert!(lines[1].contains("2760 chars of dense machine-generated content elided"));
    }

    #[test]
    fn crlf_endings_stay_on_their_line() {
        let line = "z".repeat(2500);
        let text = format!("{line}\r\nother\r\n{}", "y".repeat(2500));
        let (out, n) = elide_dense_lines(&text);
        assert_eq!(n, 2);
        assert!(out.contains('\r'));
    }
}
//! Tool-name exclusion matching (Rust port of the exclusion helpers in
//! `headroom/config.py`).
//!
//! A tool result can be excluded from compression either because the operator
//! asked for it (`--exclude-tools`) or because rewriting it would break
//! something. The second case is why the defaults exist: `headroom_retrieve`
//! returns bytes the model asked to get *back*, so recompressing them reopens
//! the retrieval loop the retrieval was meant to close.
//!
//! Matching is deliberately forgiving about spelling, because the same logical
//! tool reaches us under several names depending on the client.

use serde_json::Value;
use std::collections::HashSet;
use std::sync::OnceLock;

/// Tools whose results are never compressed by default.
/// Mirrors Python `DEFAULT_EXCLUDE_TOOLS`.
pub const DEFAULT_EXCLUDE_TOOLS: &[&str] = &[
    "Read",
    "Glob",
    "Grep",
    "Write",
    "Edit",
    "WebSearch",
    "WebFetch",
    "view",
    "headroom_retrieve",
    // Cursor's file-read tool, the same category as `Read` and `view`:
    // without this its raw source takes the LOSSY path, which is strictly
    // worse than the fold `DEFAULT_BYTE_EXACT_EXCLUDE_TOOLS` protects it
    // from below.
    "read_file",
    // Skill bodies (Claude Code's `Skill` tool) are INSTRUCTIONS, not tool
    // output: lossy compression on a directive does not degrade it, it
    // inverts it. Named below as well, because protecting a tool needs
    // both halves.
    "Skill",
    // Lowercase variants for case-insensitive matching.
    "read",
    "glob",
    "grep",
    "skill",
    "write",
    "edit",
    "web_search",
    "web_fetch",
];

/// [`DEFAULT_EXCLUDE_TOOLS`] in the comma-separated shape `--exclude-tools`
/// takes, so the flag's default and the constant above cannot drift apart.
///
/// The lowercase spellings are left out on purpose: matching is
/// case-insensitive, so listing them again would only pad `--help`.
///
/// These are the tools whose results the model is most likely to need
/// verbatim — the contents of a file it is about to edit, the exact lines a
/// search matched. Compressing those trades a few thousand tokens for the risk
/// of the model acting on a summary of a file rather than the file. Pass
/// `--exclude-tools ""` to compress them anyway.
pub const DEFAULT_EXCLUDE_TOOLS_CSV: &str =
    "Read,Glob,Grep,Write,Edit,WebSearch,WebFetch,view,read_file,Skill,headroom_retrieve";

/// Excluded tools whose results must stay *byte-faithful* — not merely
/// uncompressed. Even the excluded-tool lossless fold rewrites formatted JSON,
/// which is enough to break them.
///
/// Mirrors Python `DEFAULT_VERBATIM_EXCLUDE_TOOLS`. Removing `headroom_retrieve`
/// from this set silently reopens the retrieval loop for the cross-turn-dedup
/// path, which has no guard of its own.
pub const DEFAULT_VERBATIM_EXCLUDE_TOOLS: &[&str] = &[
    "WebSearch",
    "WebFetch",
    "web_search",
    "web_fetch",
    "view",
    "headroom_retrieve",
];

/// File-READ tools whose output the excluded-tool lossless fold must never
/// REWRITE. A strictly weaker protection than
/// [`DEFAULT_VERBATIM_EXCLUDE_TOOLS`]: this gates only the fold, so these
/// tools keep cross-turn dedup and the age-based lossy fall-through.
///
/// Mirrors Python `DEFAULT_BYTE_EXACT_EXCLUDE_TOOLS`. A read result hands
/// the fold raw file bytes; the fold inverts on our side, but the model
/// types `Edit(old_string=…)` from the bytes it was SHOWN, so a rewrite
/// breaks the anchor and the retry turn costs more than the fold saved.
/// Protecting a read tool takes both halves: excluded above so it never
/// compresses lossily, and named here so it is never folded either.
pub const DEFAULT_BYTE_EXACT_EXCLUDE_TOOLS: &[&str] =
    &["Read", "read", "read_file", "Skill", "skill"];

/// Equivalent spellings of a tool name, for exclusion matching.
/// Mirrors Python `_tool_name_aliases`.
///
/// OpenAI-style MCP wrappers use `mcp__server__tool`. Custom agents that speak
/// Anthropic sometimes emit the same wrapper as `mcp_Server_tool`. Both forms —
/// and the bare tool name — must match an entry written in any of them.
pub fn tool_name_aliases(name: &str) -> Vec<String> {
    let mut aliases = vec![name.to_string()];
    let lname = name.to_ascii_lowercase();

    // OpenCode prefixes its server name onto the tool name (upstream
    // `c7ebaedd`), so the retrieve tool arrives doubled.
    if lname == "headroom_headroom_retrieve" {
        aliases.push("headroom_retrieve".to_string());
    } else if lname.starts_with("mcp__") {
        let parts: Vec<&str> = name.splitn(3, "__").collect();
        if parts.len() == 3 && !parts[1].is_empty() && !parts[2].is_empty() {
            aliases.push(format!("mcp_{}_{}", parts[1], parts[2]));
            aliases.push(parts[2].to_string());
        }
    } else if lname.starts_with("mcp_") {
        let parts: Vec<&str> = name.splitn(3, '_').collect();
        if parts.len() == 3 && !parts[1].is_empty() && !parts[2].is_empty() {
            aliases.push(format!("mcp__{}__{}", parts[1], parts[2]));
            aliases.push(parts[2].to_string());
        }
    }

    aliases.dedup();
    aliases
}

/// True when `pattern` contains a glob metacharacter.
fn is_glob(pattern: &str) -> bool {
    pattern.contains('*') || pattern.contains('?') || pattern.contains('[')
}

/// Compile an fnmatch-style pattern to an anchored regex.
///
/// `fnmatchcase` semantics: `*` is any run, `?` is one character, `[...]` is a
/// character class with `!` (not `^`) for negation. Everything else is literal,
/// so it must be escaped — an unescaped `.` in a tool name would otherwise
/// match any character and over-exclude.
fn glob_to_regex(pattern: &str) -> Option<regex::Regex> {
    let mut out = String::with_capacity(pattern.len() * 2 + 4);
    out.push('^');
    let mut chars = pattern.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '*' => out.push_str(".*"),
            '?' => out.push('.'),
            '[' => {
                let mut class = String::from("[");
                // fnmatch spells negation `[!...]`; regex spells it `[^...]`.
                if chars.peek() == Some(&'!') {
                    chars.next();
                    class.push('^');
                } else if chars.peek() == Some(&'^') {
                    // A literal '^' first in the class; escape so regex does
                    // not read it as negation.
                    chars.next();
                    class.push_str("\\^");
                }
                let mut closed = false;
                for cc in chars.by_ref() {
                    if cc == ']' {
                        closed = true;
                        break;
                    }
                    if cc == '\\' {
                        class.push_str("\\\\");
                    } else {
                        class.push(cc);
                    }
                }
                if !closed {
                    // Unterminated class — treat the '[' as a literal, like
                    // fnmatch does.
                    out.push_str("\\[");
                    out.push_str(&regex::escape(&class[1..]));
                    continue;
                }
                class.push(']');
                out.push_str(&class);
            }
            other => out.push_str(&regex::escape(&other.to_string())),
        }
    }
    out.push('$');
    regex::Regex::new(&out).ok()
}

/// True if `name` matches the tool-exclusion set.
/// Mirrors Python `is_tool_excluded`.
///
/// Plain entries match by exact (case-insensitive) name, so the common case
/// stays a set lookup. Entries containing a glob metacharacter are matched
/// fnmatch-sty
